 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The unique foreground color marks a pattern to copy into matching all-zero spaces.
    counts = {}
    for row in grid:
        for v in row:
            if v not in (0, 1):
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return out
    color = max(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
    shape = [(r-r0, c-c0) for r, c in cells]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    # Stamp the pattern at every translation whose full footprint is currently zero.
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out
